```python
from flask import Flask, render_template, request, jsonify
import requests
import uuid
from datetime import datetime

app = Flask(__name__)

# Dados temporários (em produção use banco de dados)
sponsors = [
    {"nome": "Cafe do Centro", "logo": "https://example.com/cafe.png"},
    {"nome": "Livraria Literária", "logo": "https://example.com/livraria.png"},
    {"nome": "Restaurante Sabor", "logo": "https://example.com/restaurante.png"}
]

messages = []  # Lista de mensagens recebidas

# Configurações do Mercado Pago (substitua pelos seus dados)
MERCAIDO_PAGO_CLIENT_ID = "seu_client_id"
MERCAIDO_PAGO_SECRET = "seu_secret"
PAYMENT_URL = "https://api.mercadopago.com/payments"

def get_payment_url(amount, description):
    """Gera um link de pagamento do Mercado Pago"""
    data = {
        "client_id": MERCAIDO_PAGO_CLIENT_ID,
        "description": description,
        "amount": amount,
        "currency": "BRL",
        "return_url": "http://localhost:5000/pagamento_retorno",
        "cancel_url": "http://localhost:5000/pagamento_cancelado"
    }
    response = requests.post(PAYMENT_URL, json=data)
    return response.json().get("payment_url")

@app.route("/")
def index():
    return render_template("index.html")

@app.route("/formulario", methods=["POST"])
def formulario():
    data = request.json
    mensagem = {
        "id": str(uuid.uuid4()),
        "nome": data.get("nome", "Desconhecido"),
        "mensagem": data.get("mensagem", ""),
        "timestamp": datetime.now().isoformat()
    }
    messages.append(mensagem)
    # Manter apenas as últimas 10 mensagens
    global messages
    messages = messages[-10:]
    return jsonify({"status": "sucesso", "mensagem": "Mensagem recebida!"})

@app.route("/pagamento_retorno", methods=["POST"])
def pagamento_retorno():
    """Recebe confirmação de pagamento do Pix"""
    data = request.json
    if data.get("status") == "completado":
        # Aqui você pode registrar o pagamento
        print(f"Pagamento recebido: {data}")
    return jsonify({"status": "ok"})

@app.route("/ranking")
def ranking():
    return jsonify(sponsors)

@app.route("/ultimas_mensagens")
def ultimas_mensagens():
    return jsonify(messages)

if __name__ == "__main__":
    app.run(debug=True, host="0.0.0.0", port=5000)
```

